const puppeteer = require('puppeteer');
const path = require('path');

async function renderPoster() {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  const htmlPath = 'file://' + path.resolve('/app/output/every-child-learns-poster.html');
  console.log('Loading:', htmlPath);

  await page.goto(htmlPath, { waitUntil: 'networkidle0', timeout: 30000 });
  await page.waitForTimeout(3000); // Wait for fonts and infographics to render

  // Set viewport to A1 dimensions (at 72dpi for web)
  // A1 = 2339 x 3308 pixels at 72dpi, but we can use 2480x3508 for retina quality
  await page.setViewport({ width: 2480, height: 3508, deviceScaleFactor: 1 });

  // Wait a bit more for all rendering
  await page.waitForTimeout(2000);

  // Capture the poster container
  const posterElement = await page.$('.poster-container');
  if (!posterElement) {
    console.error('Poster container not found');
    await browser.close();
    return;
  }

  const screenshot = await posterElement.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
    fullPage: true
  });

  console.log('Poster saved to /app/output/final_poster.png');
  console.log('Screenshot size:', screenshot.length, 'bytes');

  await browser.close();
}

renderPoster().catch(err => {
  console.error('Error rendering poster:', err);
  process.exit(1);
});

